use super::*;
use crate::retained_clone::{RetainedCloneSource,RetainedCloneStep};
pub(crate) fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
pub(crate) fn retire<T:RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(bank,fuel,p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}
pub(crate) fn build(count:usize,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64)->PersistentList<u64>{let mut owner=PersistentListBuilder::new(count);let mut at=0;let mut row=None;for _ in 0..maximum{if owner.output_ready(){break}if owner.accepts_row()&&at<count{let turn=SealedShared::admit(at as u64,SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..*bank});let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();debit(bank,fuel,p,work);row=Some(value);let turn=owner.adopt(&mut row,RetainedCloneGrant{maximum_items:1,..*bank});debit(bank,fuel,turn.result.unwrap().unwrap(),turn.work);at+=1;}else if owner.accepts_row(){let turn=owner.finish(RetainedCloneGrant{maximum_items:1,..*bank});debit(bank,fuel,turn.result.unwrap().unwrap(),turn.work);}else{let turn=owner.advance(RetainedCloneGrant{maximum_items:1,..*bank},&mut None);debit(bank,fuel,turn.result.unwrap().progress(),turn.work);}}assert!(owner.output_ready());assert!(row.is_none());let turn=owner.take(RetainedCloneGrant{maximum_items:1,..*bank});let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();debit(bank,fuel,p,work);owner.begin_close();for _ in 0..maximum{if owner.terminal_is_empty(){break}let turn=owner.close_step(RetainedCloneGrant{maximum_items:1,..*bank});debit(bank,fuel,turn.result.unwrap().progress(),turn.work);}assert!(owner.terminal_is_empty());output}
enum Job{Set(PersistentSet<u64>),Splice(PersistentSplice<u64>)}
impl Job{fn ready(&self)->bool{match self{Self::Set(x)=>x.output_ready(),Self::Splice(x)=>x.output_ready()}}fn demand(&self,a:RetainedCloneRef<'_,PersistentList<u64>>,b:RetainedCloneRef<'_,SealedShared<u64>>)->Result<RetirementDemand,ValueError>{match self{Self::Set(x)=>x.demand(a,b),Self::Splice(x)=>x.demand(a,Some(b))}}fn advance(&mut self,a:RetainedCloneRef<'_,PersistentList<u64>>,b:RetainedCloneRef<'_,SealedShared<u64>>,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{match self{Self::Set(x)=>x.advance(a,b,g),Self::Splice(x)=>x.advance(a,Some(b),g)}}fn take(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<(PersistentList<u64>,RetainedCloneProgress)>>{match self{Self::Set(x)=>x.take(g),Self::Splice(x)=>x.take(g)}}fn begin_close(&mut self){match self{Self::Set(x)=>x.begin_close(),Self::Splice(x)=>x.begin_close()}}fn close(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{match self{Self::Set(x)=>x.close_step(g),Self::Splice(x)=>x.close_step(g)}}fn empty(&self)->bool{match self{Self::Set(x)=>x.terminal_is_empty(),Self::Splice(x)=>x.terminal_is_empty()}}}
#[test]fn actual_ranked_updates_keep_atomic_work_null_scratch_and_original_sources_until_paid_close(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let maximum=s["maximumTurns"].as_u64().unwrap();let count=law["inputCount"].as_u64().unwrap()as usize;let rank=law["rank"].as_u64().unwrap()as usize;let value=law["value"].as_u64().unwrap();for operation in law["operations"].as_array().unwrap(){for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap())).chain([None]){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let original=build(count,&mut bank,&mut fuel,maximum);let turn=RetainedCloneSource::admit_owned(original,(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(original,p)=turn.result.map_err(|_|()).unwrap();debit(&mut bank,&mut fuel,p,work);let turn=SealedShared::admit(value,SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();debit(&mut bank,&mut fuel,p,work);let turn=RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(authored,p)=turn.result.map_err(|_|()).unwrap();debit(&mut bank,&mut fuel,p,work);let mut job=match operation.as_str().unwrap(){"set"=>Job::Set(PersistentSet::new(rank)),"insert"=>Job::Splice(PersistentSplice::new(PersistentSpliceKind::Insert,rank)),_=>Job::Splice(PersistentSplice::new(PersistentSpliceKind::Remove,rank))};let mut injected=false;for at in 0..maximum{if cut==Some(at)||job.ready(){break}let a=original.borrow();let b=authored.borrow();let d=job.demand(a,b).unwrap();for axis in 0..5{let mut g=RetainedCloneGrant{maximum_items:1,..bank};match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.advance(a,b,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}if d.capacity_bytes>0&&!injected{let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||job.advance(a,b,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);fuel-=turn.work;assert!(turn.result.is_err());assert_eq!(job.demand(a,b).unwrap(),d);injected=true;continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.advance(a,b,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let step=turn.result.unwrap();if !job.ready(){assert!(!matches!(step,RetainedCloneStep::Complete(_)));}let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work);}if cut.is_none(){assert!(job.ready());let turn=job.take(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();debit(&mut bank,&mut fuel,p,work);let actual:Vec<_>=output.iter().copied().collect();let mut expected:Vec<u64>=(0..count as u64).collect();match operation.as_str().unwrap(){"set"=>expected[rank]=law["value"].as_u64().unwrap(),"insert"=>expected.insert(rank,law["value"].as_u64().unwrap()),_=>{expected.remove(rank);}}assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(expected).unwrap());retire(output,&mut bank,&mut fuel,maximum);}job.begin_close();for _ in 0..maximum{if job.empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.close(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,work);}assert!(job.empty());drop(job);retire(authored,&mut bank,&mut fuel,maximum);retire(original,&mut bank,&mut fuel,maximum);}}
}
